# shellcheck shell=sh
# Ryoku palette for bash (ble.sh) and zsh (zsh-syntax-highlighting). Rendered by
# the theme daemon; do not edit. ryoku.bash and ryoku.zsh source it before they
# set their syntax faces, and fall back to the default palette without it, the
# same split fish takes with conf.d/ryoku-colors.fish.
RYOKU_SYNTAX_COMMAND='{{colors.primary.default.hex}}'
RYOKU_SYNTAX_KEYWORD='{{colors.tertiary.default.hex}}'
